            st.party.formed = true;
            st.rng.seed(1);
            st.hideExplore();
            if (st.turnCount != 1) ++bad;
            if (st.hiddenThief) ++bad;
            if (st.log.get(0).find(
                    "the shadows stay empty")
                == std::string::npos) ++bad;
