            st.springTrap(0);
            if (st.turnCount != 0) ++bad;
            if (st.party.members[0].hp != 22) ++bad;
            if (st.log.get(0).find("hauls")
                != std::string::npos) ++bad;
            if (st.log.get(0).find("ropes")
                != std::string::npos) ++bad;
