            if (st.party.gold != 240) ++bad;
            if (st.party.delveGold != 240) ++bad;
            if (st.log.get(0).find(
                    "a cache holds 240 gp")
                == std::string::npos) ++bad;
            std::string snap = st.log.get(0);
            st.readScript();
            if (st.party.gold != 240) ++bad;
