        if (rules::uwSpecialCrossbowPriceMultiple()
                != 10 ||
            rules::uwSpecialCrossbowRangeDivisor()
                != 2 ||
            rules::uwNetThrowFtPerStrPoint() != 1 ||
            rules::uwNetThrowUnderwaterRaceFt()
                != 15 ||
            rules::uwNetThrowSahuaginFt() != 20 ||
            rules::uwNetUntrainedPenalty() != 4)
            ++bad;
