            m.name = "Monst";
            m.hp = 6; m.maxHp = 6;
            mons.push_back(m);
            ai::Encounter enc(pt, mons, 20);
            enc.resolveCast(
                enc.partyMutable()[0],
                spells::DR_WATER_BREATHING);
            if (enc.breathActive()) ++bad;
            bool br = false;
            for (const auto& ln : enc.log())
                if (ln.text.find("breathes water freely") !=
                    std::string::npos)
                    br = true;
            if (br) ++bad;
