            if (cavMoneyDiceFaces(3) != 12) ++bad;
            if (cavMoneyDiceFaces(4) != 6) ++bad;
            if (cavMoneyDiceBonus(4) != 6) ++bad;
            if (cavMoneyDiceBonus(5) != 12) ++bad;
            // the Horseman rows print no
