            if (uamtAcAdjustment(8, 2) != -7) ++bad;
            if (uamtAcAdjustment(14, 0) != -4) ++bad;
            if (uamtAcAdjustment(14, 5) != 0) ++bad;
            if (uamtAcAdjustment(1, 5) != -1) ++bad;
            if (uamtAcAdjustment(1, 6) != 0) ++bad;
            if (uamtAcAdjustment(9, 6) != 0) ++bad;
