            if (uamtAcAdjustment(6, 4) != 0) ++bad;
            if (uamtAcAdjustment(6, 5) != 1) ++bad;
            if (uamtAcAdjustment(6, 6) != 2) ++bad;
            // the recovered census: every one of the
