    // ---- R368: the UA Cavaliers Table I
    // pin audit ----
    // The UA CAVALIERS TABLE I (p. 15): the
    // full table pinned - the two 0-level
    // rows (Horseman 1d4+1 at -1,500 to
    // -501, Lancer 2d4+1 at -500 to -1),
    // the 1st-level footnote (the track
    // 3d4+1 vs the direct 1d10+3), the
    // printed XP bands with the level-11
    // band decoded from its neighbors, the
    // cumulative dice column (the level
    // count at 2nd-10th, 10+3 and 10+6 at
    // 11th and 12th), the level titles (the
    // 11th and 12th cells newly readable -
    // two of the four R328 holes close; the
    // level-5 grid Knight with the prose
    // conflict flagged; the level-6 cell
    // lost, a hole; the 12-sided header cell
    // suspect against the R327 d10), the 3
    // hp per level past 10th, the 300,000
    // xp per level past 12th and Cavalier
    // Commander at 13th+. The R328 seam
    // cross-checks the XP ladder and the
    // known titles. The item flips CLOSED;
    // the census 294 -> 295.
    {
        using namespace rules;
        int bad = 0;
        // ---- the pinned cells ----
            if (uacavtHorsemanXpLow() != -1500) ++bad;
            if (uacavtHorsemanXpHigh() != -501) ++bad;
            if (uacavtHorsemanHpDice() != 1) ++bad;
            if (uacavtHorsemanHpDiceSides() != 4) ++bad;
            if (uacavtHorsemanHpBonus() != 1) ++bad;
            if (uacavtLancerXpLow() != -500) ++bad;
            if (uacavtLancerXpHigh() != -1) ++bad;
            if (uacavtLancerHpDice() != 2) ++bad;
            if (uacavtLancerHpDiceSides() != 4) ++bad;
            if (uacavtLancerHpBonus() != 1) ++bad;
            if (!uacavtFirstLevelTrackFootnote()) ++bad;
            if (uacavtTrackFirstDice() != 3) ++bad;
            if (uacavtTrackFirstSides() != 4) ++bad;
            if (uacavtTrackFirstBonus() != 1) ++bad;
            if (uacavtDirectFirstDice() != 1) ++bad;
            if (uacavtDirectFirstSides() != 10) ++bad;
            if (uacavtDirectFirstBonus() != 3) ++bad;
            if (!uacavtLevel12XpUnbounded()) ++bad;
            if (!uacavtLevel11BandDecoded()) ++bad;
            if (uacavtLevel11FlatHp() != 3) ++bad;
            if (uacavtLevel12FlatHp() != 6) ++bad;
            if (uacavtHpPerLevelPast10() != 3) ++bad;
            if (!uacavtDiceColumnCumulative()) ++bad;
            if (!uacavtTwelveSidedHeaderSuspect()) ++bad;
            if (!uacavtLevel6TitleCellLost()) ++bad;
            if (!uacavtLevel5GridVsProseConflict()) ++bad;
            if (uacavtXpPerLevelPast12() != 300000) ++bad;
            if (uacavtCommanderLevel() != 13) ++bad;
        // ---- the XP band loops ----
            static const int xl[12] = {0,
                2501, 5001, 10001, 18501,
                37001, 85001, 140001,
                220001, 300001, 600001,
                900001};
            static const int xh[12] = {2500,
                5000, 10000, 18500, 37000,
                85000, 140000, 220000,
                300000, 600000, 900000, 0};
            for (int l = 1; l <= 12; ++l) {
                if (uacavtLevelXpLow(l) != xl[l - 1])
                    ++bad;
                if (uacavtLevelXpHigh(l) != xh[l - 1])
                    ++bad;
                if (l < 12 && xh[l - 1] + 1 != xl[l]) ++bad;
                // the R328 seam:
                // attain(l) = high(l-1)
                int att = cavalierXpToAttain(l);
                if (l == 1) {
                    if (att != 0) ++bad;
                } else if (att != xh[l - 2]) {
                    ++bad;
                }
            }
            if (uacavtHorsemanXpLow() != cavalierHorsemanXp())
                ++bad;
            if (uacavtLancerXpLow() != cavalierLancerXp())
                ++bad;
        // ---- the dice column ----
            for (int l = 2; l <= 10; ++l) {
                if (uacavtLevelDiceCount(l) != l)
                    ++bad;
            }
            if (uacavtLevelDiceCount(11) != 10) ++bad;
            if (uacavtLevelDiceCount(12) != 10) ++bad;
            if (uacavtLevel11FlatHp() != uacavtHpPerLevelPast10())
                ++bad;
            if (uacavtLevel12FlatHp() != 2 * uacavtHpPerLevelPast10())
                ++bad;
            if (uacavtHpPerLevelPast10() != cavalierHpPerLevelPast10())
                ++bad;
        // ---- the titles ----
            static const char* const tn[14] = {
                "Horseman", "Lancer", "Armiger",
                "Scutifer", "Esquire", "Knight Errant",
                "Knight", "", "Grand Knight",
                "Banneret", "Chevalier", "Cavalier",
                "Cavalier, 11th", "Cavalier, 12th"};
            for (int i = 0; i < 14; ++i) {
                int l = (i == 0) ? 0 : (i == 1 ? -1 : i - 1);
                if (strcmp(uacavtTitle(l), tn[i]) != 0)
                    ++bad;
            }
            if (strcmp(uacavtTitle(13),
                    "Cavalier Commander") != 0)
                ++bad;
            if (uacavtCommanderLevel() != cavalierCommanderLevel())
                ++bad;
            if (uacavtXpPerLevelPast12() != cavalierXpPerLevelPast12())
                ++bad;
            // the R328 known-title seam
            for (int l = 1; l <= 10; ++l) {
                if (l == 5 || l == 6) continue;
                if (strcmp(uacavtTitle(l),
                        cavalierTitleKnown(l)) != 0)
                    ++bad;
            }
            // the newly readable 11th and
            // 12th cells (the R328 hole
            // record returns the empty
            // string - no seam check)
            if (uacavtTitle(11)[0] == 0)
                ++bad;
            if (uacavtTitle(12)[0] == 0)
                ++bad;
        printf("R368 UA Cavaliers Table I pin audit: bad %d\n", bad);
        if (bad) return 1;
    }

    // ---- R369: the UA cantrip
    // acquisition pin audit ----
    // The UA ACQUISITION OF CANTRIPS,
    // MAGIC-USERS (p. 79): the known-count
    // rules pinned - the useful category
    // one per point of intelligence by free
    // choice (the decode flagged), the five
    // random bands (reversed 2-8, legerdemain
    // 2-5, person-affecting 2-8, personal
    // 2-8, haunting-sound 2-5), the 3
    // developed cap with the DM review, the
    // read-as-spell and recorded-as-spell
    // notes. The R365 seam cross-checks the
    // illusionist bands (the documented
    // divergence); the R366 seam the book
    // counts. The item flips CLOSED; the
    // census 295 -> 296.
    {
        using namespace rules;
        int bad = 0;
        // ---- the pinned cells ----
            if (uacaqUsefulPerIntelligencePoint()
                    != 1) ++bad;
            if (!uacaqUsefulFreeChoice()) ++bad;
            if (!uacaqUsefulReadDecoded()) ++bad;
            if (uacaqCategoryCount() != 6) ++bad;
            if (uacaqReversedKnownMin() != 2)
                ++bad;
            if (uacaqReversedKnownMax() != 8)
                ++bad;
            if (uacaqLegerdemainKnownMin() != 2)
                ++bad;
            if (uacaqLegerdemainKnownMax() != 5)
                ++bad;
            if (uacaqPersonAffectingKnownMin() != 2)
                ++bad;
            if (uacaqPersonAffectingKnownMax() != 8)
                ++bad;
            if (uacaqPersonalKnownMin() != 2)
                ++bad;
            if (uacaqPersonalKnownMax() != 8)
                ++bad;
            if (uacaqHauntingSoundKnownMin() != 2)
                ++bad;
            if (uacaqHauntingSoundKnownMax() != 5)
                ++bad;
            if (uacaqMaxDevelopedCantrips() != 3)
                ++bad;
            if (!uacaqDevelopedRequiresDmReview())
                ++bad;
            if (!uacaqReadAsSpell()) ++bad;
            if (!uacaqRecordedAsSpell()) ++bad;
        // ---- the R365 illusionist seam ----
            // The documented MU-vs-illusionist
            // divergences (the bands differ by
            // design; the illusionist useful cap
            // is intelligence minus 3):
            if (uacaqReversedKnownMax()
                    == uailaReversedKnownMax())
                ++bad;
            if (uacaqLegerdemainKnownMin()
                    == uailaLegerdemainKnownMin())
                ++bad;
            if (uacaqPersonAffectingKnownMax()
                    == uailaPersonAffectingKnownMax())
                ++bad;
            if (uacaqPersonalKnownMax()
                    == uailaPersonalKnownMax())
                ++bad;
            if (uacaqHauntingSoundKnownMax()
                    == uailaHauntingSoundKnownMax())
                ++bad;
            if (uacaqUsefulPerIntelligencePoint()
                    * 18 - uailaUsefulCapAtInt18()
                    != uailaUsefulCapIntMinus())
                ++bad;
            if (!uailaHasAllMuCantrips()) ++bad;
            if (!uailaMuCantripPropertiesOtherwiseApply())
                ++bad;
            // The seven-category read: the six
            // MU categories plus the
            // illusionist-only minor illusion.
            if (uacaqCategoryCount() + 1 != 7)
                ++bad;
        // ---- the R366 spell-book seam ----
            if (!uabkCantripsCountAsFirstLevel())
                ++bad;
            if (uabkStandardCantripsCapacity()
                    != 36) ++bad;
        printf("R369 UA cantrip acquisition pin audit: bad %d\n", bad);
        if (bad) return 1;
    }


    // ---- R370: the UA DM-section
    // smalls pin audit ----
    // The UA DM-section smalls, part 1:
    // Method V (p. 74) - the class-first
    // humans-only generation, the
    // best-three-of-N roll with the DM
    // approval, the minimum and maximum
    // clamps, the 9d6 fighter strength
    // example (the dice table cells lost,
    // flagged); the starting hit-point
    // minimums (p. 74) - the 12 class
    // floors, the multi-class average
    // rounded up, the constitution
    // adjustment; the warhorses and
    // barding (p. 76) - the movement rate
    // table (the medium scale and heavy
    // leather cells lost, flagged), the
    // endurance rule, the magical barding
    // costs and percentages, the flying
    // and aquatic steeds rules. The R368
    // seam cross-checks the cavalier d10
    // floor. Three items flip CLOSED; the
    // census 296 -> 297.
    {
        using namespace rules;
        int bad = 0;
        // ---- Method V ----
            if (!uasm1MethodVHumansOnly()) ++bad;
            if (!uasm1MethodVClassFirst()) ++bad;
            if (!uasm1MethodVRequiresDmApproval())
                ++bad;
            if (!uasm1MethodVBestThreeOfN()) ++bad;
            if (!uasm1MethodVMinClampApplies())
                ++bad;
            if (!uasm1MethodVMaxClampApplies())
                ++bad;
            if (uasm1MethodVFighterStrengthDice()
                    != 9) ++bad;
            if (uasm1MethodVTableCellsLost())
                ++bad;
        // ---- the starting hit points ----
            if (uasm1StartHpClassCount() != 12)
                ++bad;
            static const int hp[12] = {6, 6,
                5, 5, 6, 7, 9, 3, 3, 4, 4, 5};
            for (int i = 0; i < 12; ++i) {
                if (uasm1StartHpMin(i) != hp[i])
                    ++bad;
            }
            if (!uasm1StartHpMultiClassAverageRoundedUp())
                ++bad;
            if (uasm1StartHpExampleFighterMage()
                    != 5) ++bad;
            if (!uasm1StartHpConAdjustApplies())
                ++bad;
            if (uasm1StartHpExampleCon17Fighter()
                    != 9) ++bad;
            // the multi-class read: the
            // average of the minimums,
            // rounded up
            if ((6 + 3 + 1) / 2
                    != uasm1StartHpExampleFighterMage())
                ++bad;
            // the con-17 example: the
            // fighter floor plus the +3
            if (uasm1StartHpMin(4) + 3
                    != uasm1StartHpExampleCon17Fighter())
                ++bad;
        // ---- the barding table ----
            if (uasm1BardLightLeather() != 21)
                ++bad;
            if (!uasm1BardLightChainNa())
                ++bad;
            if (uasm1BardLightScale() != 15)
                ++bad;
            if (uasm1BardLightScaleNa()) ++bad;
            if (!uasm1BardLightPlateNa()) ++bad;
            if (uasm1BardMediumLeather() != 17)
                ++bad;
            if (uasm1BardMediumChain() != 12)
                ++bad;
            if (uasm1BardMediumScaleCellLost())
                ++bad;
            if (uasm1BardMediumScale() != 15)
                ++bad;
            if (!uasm1BardMediumPlateNa()) ++bad;
            if (uasm1BardHeavyLeatherCellLost())
                ++bad;
            if (uasm1BardHeavyLeather() != 15)
                ++bad;
            if (uasm1BardHeavyChain() != 13)
                ++bad;
            if (uasm1BardHeavyScale() != 14)
                ++bad;
            if (uasm1BardHeavyPlate() != 12)
                ++bad;
            // the movement monotonicity:
            // heavier barding, slower
            if (uasm1BardHeavyLeather()
                    <= uasm1BardHeavyScale()) ++bad;
            if (uasm1BardHeavyChain()
                    <= uasm1BardHeavyPlate()) ++bad;
            if (uasm1BardLightLeather()
                    <= uasm1BardMediumLeather())
                ++bad;
            if (!uasm1BardEnduranceFromBaseRate())
                ++bad;
        // ---- the magical barding ----
            if (uasm1MagBardingCostMultiple()
                    != 5) ++bad;
            if (uasm1MagBardingPlusCap() != 3)
                ++bad;
            if (uasm1MagBardingPlus1Pct()
                    + uasm1MagBardingPlus2Pct()
                    + uasm1MagBardingPlus3Pct()
                    != 100) ++bad;
            if (uasm1MagBardingLeatherPct()
                    + uasm1MagBardingScalePct()
                    + uasm1MagBardingChainPct()
                    + uasm1MagBardingPlatePct()
                    != 100) ++bad;
            if (uasm1MagBardingPlus1Pct()
                    != 65) ++bad;
            if (uasm1MagBardingPlus2Pct()
                    != 25) ++bad;
            if (uasm1MagBardingPlus3Pct()
                    != 10) ++bad;
            if (uasm1MagBardingLeatherPct()
                    != 10) ++bad;
            if (uasm1MagBardingScalePct()
                    != 15) ++bad;
            if (uasm1MagBardingChainPct()
                    != 25) ++bad;
            if (uasm1MagBardingPlatePct()
                    != 50) ++bad;
        // ---- the other steeds ----
            if (!uasm1FlyingSteedsLeatherOrElfinOnly())
                ++bad;
            if (!uasm1FlyingSteedsReductionEighth())
                ++bad;
            if (!uasm1AquaticSteedsNotBarded())
                ++bad;
            if (uasm1StrongMountPlateReductionMin()
                    != 5) ++bad;
            if (uasm1StrongMountPlateReductionMax()
                    != 8) ++bad;
            if (!uasm1UnicornGriffonElfinWeightAsLeather())
                ++bad;
        // ---- the R368 seam ----
            // the cavalier starting floor
            // (6) cannot exceed the d10
            // level-1 hit die the R368 pin
            // carries
            if (uasm1StartHpMin(0)
                    > uacavtDirectFirstSides())
                ++bad;
        printf("R370 UA DM-section smalls pin audit: bad %d\n", bad);
        if (bad) return 1;
    }


    // ---- R371: the UA expanded armor
    // pin audit ----
    // The UA expanded armor (pp. 75-76):
    // the armor and encumbrance table
    // rows (banded through studded
    // leather, the shield rows, the
    // never-sold elfin chain footnote)
    // and the four descriptions - the
    // bronze plate (the AC 4, the +2
    // rear-attack exposure, the rust
    // immunity), the elfin chain (the
    // thief-wearable read), the field
    // plate (the 1 point per die
    // absorption, the 12 point cap, the
    // 100 gp per point repair), the full
    // plate. The R191 seam cross-checks
    // the plate AC ladder, the R334 seam
