    // ---- R499 WSG temperature fold audit ----
    // The WSG temperature-chain fold, the first seam round after gap closure:
    // no new book pages. Every pinned value is a landed original re-read from
    // its header and pinned again on the fold side, so each identity compiles
    // and rides the mutant battery. The chain: one wilderness temperature
    // feeds the dress Table 3 column dispatch (rules/wsgdress.h
    // wsdColForTemp, boundaries below 0, 0-30, 31-75, 76 plus), the Table 9
    // damage band dispatch (rules/wsgheat.h wshHeatBandFor, 25 bands,
    // no-damage band 16 at 31-84, frostbite threshold 0), the weather letter
    // codes (rules/wsgweather.h wwsTempCodeHi, D tops at 0, H at 30) and the
    // R498 survival shifts (plus 20 at 30 or lower, minus 20 at 80 or
    // higher). Three boundary alignments are true (31 with 31, 30 with 30, 0
    // with 0); one is a deliberate non-alignment (the hot column opens at 76,
    // eight degrees inside the no-damage band - attire adjusts before damage
    // resumes at 85); the protected no-damage span is wider on both ends (6
    // through 89).
    {
        using namespace rules;
        int bad = 0;
    if (wtfDressColCount() != 4
            || wtfDressBelow0Bound() != 0
            || wtfDressColdTop() != 30
            || wtfDressModLo() != 31
            || wtfDressModTop() != 75
            || wtfDressHotLo() != 76
            || wtfBandCount() != 25
            || wtfBandNoDmg() != 16
            || wtfNoDmgLo() != 31
            || wtfNoDmgHi() != 84
            || wtfDmgResume() != 85
            || wtfBandFrostTop() != 0
            || wtfBandPreNoDmgTop() != 30
            || wtfFrostMax() != 0
            || wtfDash() != 99
            || wtfDashUnprot() != 2
            || wtfDashProt() != 14
            || wtfProtNoDmgLo() != 6
            || wtfProtNoDmgHi() != 89
            || wtfCodeCount() != 26
            || wtfCodeDHi() != 0
            || wtfCodeHHi() != 30
            || wtfCodePeakHi() != 115
            || wtfSurvColdShift() != 20
            || wtfSurvColdBound() != 30
            || wtfSurvHeatShift() != 20
            || wtfSurvHeatBound() != 80
            || !wtfModOpensWithNoDmg()
            || !wtfFrostAtBelow0Bound()
            || !wtfBand15TopsWithColdCol()
            || !wtfHotOpensInsideNoDmg()
            || !wtfModNarrowerThanNoDmg()
            || !wtfSurvColdLandsNoDmg()
            || !wtfSurvHeatLandsModCol()
            || !wtfProtWiderThanUnprot()
            || !wtfCodesSpanChain()
            || !wtfChainHasNoGaps()
        )
            ++bad;
        // the dress column boundaries
    if (wtfDressColCount() != 4
            || wtfDressBelow0Bound() != 0
            || wtfDressColdTop() != 30
            || wtfDressModLo() != 31
            || wtfDressModTop() != 75
            || wtfDressHotLo() != 76
        )
            ++bad;
        // the moderate column opens exactly where the no-damage band opens -
        // the first true alignment
    if (wtfDressModLo() != wtfNoDmgLo()
        )
            ++bad;
        // the frostbite threshold sits at the below-0 boundary value
    if (wtfFrostMax() != wtfDressBelow0Bound()
            || wtfBandFrostTop() != wtfDressBelow0Bound()
        )
            ++bad;
        // band 15 tops where the cold column tops - the second true alignment
    if (wtfBandPreNoDmgTop() != wtfDressColdTop()
        )
            ++bad;
        // the hot column opens inside the no-damage band
    if (wtfDressHotLo() < wtfNoDmgLo()
            || wtfDressHotLo() > wtfNoDmgHi()
        )
            ++bad;
        // the overlap runs eight degrees
    if (wtfNoDmgHi() - wtfDressHotLo() != 8
        )
            ++bad;
        // the moderate column is narrower than the no-damage band
    if (wtfDressModTop() >= wtfNoDmgHi()
        )
            ++bad;
        // unprotected damage resumes one degree past the no-damage top
    if (wtfDmgResume() != wtfNoDmgHi() + 1
        )
            ++bad;
        // the dash censuses match Table 9
    if (wtfDashUnprot() + wtfDashProt() != 16
            || wtfDash() != 99
        )
            ++bad;
        // protected no-damage is wider on both ends
    if (wtfProtNoDmgLo() >= wtfNoDmgLo()
            || wtfProtNoDmgHi() <= wtfNoDmgHi()
        )
            ++bad;
        // cold survival at its bound lands inside the no-damage band
    if (wtfSurvColdBound() + wtfSurvColdShift() < wtfNoDmgLo()
            || wtfSurvColdBound() + wtfSurvColdShift() > wtfNoDmgHi()
        )
            ++bad;
        // heat survival at its bound lands inside the moderate column
    if (wtfSurvHeatBound() - wtfSurvHeatShift() < wtfDressModLo()
            || wtfSurvHeatBound() - wtfSurvHeatShift() > wtfDressModTop()
        )
            ++bad;
        // the letter codes bracket the chain
    if (wtfCodeCount() != 26
            || wtfCodeDHi() != wtfFrostMax()
            || wtfCodeHHi() != wtfDressColdTop()
            || wtfCodePeakHi() < 90
        )
            ++bad;
        printf("R499 WSG temperature fold audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R500 WSG swimmer motion fold audit ----
    // The WSG swimmer's motion-chain fold, the second seam round after gap
    // closure: no new book pages, the R499 pattern applied to the water
    // chapter. One swimmer state flows through five landed headers: the
    // swimming rates (rules/wsgswim.h R450: 40 feet base, the 2/3 subsurface
    // cut, the 2x high speed with the 1/10 endurance cut, the 3-per-turn rest
    // regain, the 1-3/4-6 inch current ranges), the dive leg (rules/wsgdive.h
    // R452: the 2 inch or 20 foot base, doubled moderate and tripled heavy),
    // the surfacing leg (rules/wsgbreath.h R454: the same 2 inch base, the 5
    // foot inert buoyancy rise), the moving-water hazards (rules/wsgmwater.h
    // R451: the 1-10 stream rating, the two-round hold cadence, the 40/100
    // foot waterfall thresholds, the half and tenth damage divisors) and the
    // treading economy (rules/wsgtread.h R453: 2 turns per endurance point, 1
    // round per strength point, the +1 check ladder). The findings: the
    // vertical rates equal each other and are half the horizontal base; the
    // Table 24 dive column matches the dive prose exactly; the encumbrance
    // paradox (the same weight that halves speed doubles the sink rate); the
    // forty-foot agreement between the dive falling-damage threshold and the
    // waterfall save threshold; and the two different cumulative check
    // ladders (+2 breath, +1 treading).
    {
        using namespace rules;
        int bad = 0;
    if (wmfSwimRateFt() != 40
            || wmfOtherRateFt() != 30
            || wmfSubsurfNum() != 2
            || wmfSubsurfDen() != 3
            || wmfHighSpeedMult() != 2
            || wmfHighSpeedEndDiv() != 10
            || wmfRestRegainPerTurn() != 3
            || wmfLightCurMaxIn() != 3
            || wmfStrongCurMinIn() != 4
            || wmfStrongCurMaxIn() != 6
            || wmfMercyDriftMaxIn() != 3
            || wmfDownRateIn() != 2
            || wmfDownRateFt() != 20
            || wmfDiveEncModMult() != 2
            || wmfDiveEncHeavyMult() != 3
            || wmfSurfRateIn() != 2
            || wmfInertRiseFt() != 5
            || wmfLeapCapIn() != 5
            || wmfStreamRateMin() != 1
            || wmfStreamRateMax() != 10
            || wmfHoldCheckPeriod() != 2
            || wmfWaterfallMinFt() != 40
            || wmfWaterfallMaxFt() != 100
            || wmfHighDiveMinFt() != 40
            || wmfFallDmgDiv() != 2
            || wmfLongFallDiv() != 10
            || wmfBreathConDiv() != 3
            || wmfMinBreathRounds() != 1
            || wmfPenaltyDiv() != 2
            || wmfBothPenaltyDiv() != 4
            || wmfConCheckStep() != 2
            || wmfBreathExampleRounds() != 4
            || wmfTreadTurnsPerEndPt() != 2
            || wmfTreadRoundsPerStrPt() != 1
            || wmfTreadCheckStep() != 1
            || wmfTreadExampleRounds() != 12
            || wmfEncMultUnenc() != 2
            || wmfSpdDenMod() != 2
            || wmfSpdDenHeavy() != 4
            || !wmfVerticalRatesEqual()
            || !wmfVerticalHalfHorizontal()
            || !wmfDiveGridMatchesProse()
            || !wmfEncumbranceParadox()
            || !wmfFortyFootAgreement()
            || !wmfMercyMatchesLightCur()
            || !wmfCheckStepsDiffer()
            || !wmfEconomiesDiffer()
            || !wmfSubsurfaceBeforeHighSpeed()
            || !wmfInertQuarterOfDeliberate()
        )
            ++bad;
        // the horizontal base rates
    if (wmfSwimRateFt() != 40
            || wmfOtherRateFt() != 30
            || wmfHighSpeedMult() != 2
            || wmfHighSpeedEndDiv() != 10
            || wmfRestRegainPerTurn() != 3
        )
            ++bad;
        // the vertical rates are equal - the first true alignment
    if (wmfDownRateIn() != wmfSurfRateIn()
        )
            ++bad;
        // the vertical base is half the horizontal base
    if (wmfSwimRateFt() / wmfDownRateFt() != 2
        )
            ++bad;
        // the Table 24 dive column matches the dive prose - doubled at
        // moderate, tripled at heavy and severe
    if (wmfDiveEncModMult() != 2
            || wmfDiveEncHeavyMult() != 3
        )
            ++bad;
        // the encumbrance paradox: the moderate speed denominator equals the
        // moderate dive multiplier
    if (wmfSpdDenMod() != wmfDiveEncModMult()
        )
            ++bad;
        // at heavy the grids diverge: quarter speed, triple sink
    if (wmfSpdDenHeavy() == wmfDiveEncHeavyMult()
        )
            ++bad;
        // the forty-foot agreement - the dive and waterfall thresholds are
        // the same value
    if (wmfHighDiveMinFt() != wmfWaterfallMinFt()
        )
            ++bad;
        // the save window spans sixty feet
    if (wmfWaterfallMaxFt() - wmfWaterfallMinFt() != 60
        )
            ++bad;
        // the mercy drift cap equals the light-current range
    if (wmfMercyDriftMaxIn() != wmfLightCurMaxIn()
        )
            ++bad;
        // the breath formula and penalties
    if (wmfBreathConDiv() * wmfBreathExampleRounds() != 12
            || wmfBothPenaltyDiv() != wmfPenaltyDiv() * 2
            || wmfMinBreathRounds() != 1
        )
            ++bad;
        // the check steps differ by one - the treading ladder is gentler than
        // the breath ladder
    if (wmfConCheckStep() - wmfTreadCheckStep() != 1
        )
            ++bad;
        // the treading example: strength 6 doubled by the unencumbered
        // endurance modifier
    if (wmfTreadExampleRounds() != 6 * wmfEncMultUnenc()
        )
            ++bad;
        // the stream rating and the hold cadence
    if (wmfStreamRateMax() - wmfStreamRateMin() != 9
            || wmfHoldCheckPeriod() != 2
        )
            ++bad;
        // the inert rise is one quarter of the deliberate rate
    if (wmfDownRateFt() / wmfInertRiseFt() != 4
        )
            ++bad;
        // the subsurface cut is two thirds
    if (wmfSubsurfDen() * 2 != wmfSubsurfNum() * 3
        )
            ++bad;
        // the leap cap matches the vertical base in inches
    if (wmfLeapCapIn() != wmfDownRateIn() + 3
        )
            ++bad;
        printf("R500 WSG swimmer motion fold audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R501 WSG movement fall fold audit ----
    // The WSG movement/fall-chain fold, the third seam round after gap
    // closure: no new book pages, the R499 pattern applied to the
    // climbing-and-falling chapter. One falling character flows through seven
    // landed headers: the climbing ratings (rules/wsgclimb.h R435: the 40
    // percent non-thief, the 80 percent mountaineer, the fall chance as 100
    // minus the rating), the Table 17 fall ladder (rules/wsgfall.h R437: the
    // six bands 1, 3, 6, 10, 15, 20 dice, the 1000-foot free-fall rate, the
    // 600-800 severe slope), the tumble rates (rules/wsgtumble.h R438: the
    // 10-foot abrasion granularity, the 100-300 gentle and 300-500 moderate
    // rates), the stop windows (rules/wsgstop.h R439: 50 feet cliff or
    // severe, 75 moderate, 100 gentle), the jump floors (rules/wsgjump.h
    // R448: the 2-foot broad and 1-foot high floors, the 20-foot run, the 1d3
    // heap at 5 feet), the slippery-surface cadence (rules/wsgslip.h R447:
    // the five-segment run check, the half-rate caution) and the airborne
    // fall chance (rules/wsgfallair.h R461: the zero base, the -200/-150
    // straps, the -50 proficiency, the -10 saddle and stirrups). The
    // findings: the Table 17 dice are the triangular numbers (increments 2,
    // 3, 4, 5) and the 51-or-more band caps at 20d6 ONE DIE SHORT of the pure
    // sequence value 21; the prose linear 1d6-per-10-feet understates the
    // printed table (3d6 at 20 feet, not 2d6); the cliff/severe stop window
    // of 50 feet is exactly the top of the 41-50 damage band; the gentle stop
    // window equals the gentle tumble rate minimum; the rate ladder is
    // contiguous (100-300, 300-500, 600-800, 1000); and the horizontal slip
    // deals no direct damage while the inclined tumble abrasion kills.
    {
        using namespace rules;
        int bad = 0;
    if (wmvFallBandCount() != 6
            || wmvFallFirstBandFt() != 10
            || wmvFallOpenBandFt() != 51
            || wmvFallDiceB0() != 1
            || wmvFallDiceB1() != 3
            || wmvFallDiceB2() != 6
            || wmvFallDiceB3() != 10
            || wmvFallDiceB4() != 15
            || wmvFallDiceB5() != 20
            || wmvMaxFallDice() != 20
            || wmvFreeFallRate() != 1000
            || wmvSevereRateMin() != 600
            || wmvSevereRateMax() != 800
            || wmvAbrasionPerFt() != 10
            || wmvGentleTumbleMin() != 100
            || wmvGentleTumbleMax() != 300
            || wmvModerateTumbleMin() != 300
            || wmvModerateTumbleMax() != 500
            || wmvStopCliffSevereFt() != 50
            || wmvStopModerateFt() != 75
            || wmvStopGentleFt() != 100
            || wmvNonThiefRating() != 40
            || wmvMountaineerRating() != 80
            || wmvFallBase() != 100
            || wmvRunRequiredFt() != 20
            || wmvRunningAdvantageFt() != 4
            || wmvHeapDmgDie() != 3
            || wmvHeapMinFt() != 5
            || wmvStandFloorFt() != 2
            || wmvHighFloorFt() != 1
            || wmvHighHorizDiv() != 2
            || wmvSlipRunCheckSegs() != 5
            || wmvCautiousRateDiv() != 2
            || wmvAirBaseFallPct() != 0
            || wmvStrapFullBodyPct() != -200
            || wmvStrapLowerBodyPct() != -150
            || wmvAirborneProfPct() != -50
            || wmvSaddlePct() != -10
            || wmvStirrupsPct() != -10
            || !wmvDiceLadderTriangular()
            || !wmvCapBreaksSequence()
            || !wmvProseVsTableTension()
            || !wmvStopWindowBandTop()
            || !wmvGentleWindowEqualsRate()
            || !wmvRateLadderContiguous()
            || !wmvTenFootGranularity()
            || !wmvSlipHarmlessTumbleDeadly()
            || !wmvClimbFallIsComplement()
            || !wmvAirLadderOrdered()
        )
            ++bad;
        // the Table 17 dice ladder
    if (wmvFallBandCount() != 6
            || wmvFallDiceB0() != 1
            || wmvFallDiceB1() != 3
            || wmvFallDiceB2() != 6
            || wmvFallDiceB3() != 10
            || wmvFallDiceB4() != 15
            || wmvFallDiceB5() != 20
        )
            ++bad;
        // the ladder is triangular: each band adds one more die than the
        // previous band added
    if (wmvFallDiceB1() - wmvFallDiceB0() != 2
            || wmvFallDiceB2() - wmvFallDiceB1() != 3
            || wmvFallDiceB3() - wmvFallDiceB2() != 4
            || wmvFallDiceB4() - wmvFallDiceB3() != 5
        )
            ++bad;
        // the cap breaks the sequence: the last increment repeats instead of
        // stepping to six - 20, not 21
    if (wmvFallDiceB5() - wmvFallDiceB4() != 5
            || wmvFallDiceB5() == wmvFallDiceB4() + 6
            || wmvMaxFallDice() != wmvFallDiceB5()
        )
            ++bad;
        // the open band opens one foot past the stop window
    if (wmvFallOpenBandFt() - wmvStopCliffSevereFt() != 1
        )
            ++bad;
        // the gentle stop window equals the gentle tumble rate minimum
    if (wmvStopGentleFt() != wmvGentleTumbleMin()
        )
            ++bad;
        // the rate ladder is contiguous and strictly ascending
    if (wmvGentleTumbleMax() != wmvModerateTumbleMin()
            || wmvModerateTumbleMax() >= wmvSevereRateMin()
            || wmvSevereRateMax() >= wmvFreeFallRate()
        )
            ++bad;
        // the climb fall chance is the complement of the rating
    if (wmvFallBase() - wmvNonThiefRating() != 60
            || wmvFallBase() - wmvMountaineerRating() != 20
        )
            ++bad;
        // the jump floors and the heap
    if (wmvStandFloorFt() != 2
            || wmvHighFloorFt() != 1
            || wmvHeapMinFt() != 5
            || wmvHeapDmgDie() != 3
            || wmvRunRequiredFt() != 20
        )
            ++bad;
        // the slip cadence and the cautious divisor
    if (wmvSlipRunCheckSegs() != 5
            || wmvCautiousRateDiv() != 2
        )
            ++bad;
        // the airborne reduction ladder is ordered
    if (wmvStrapFullBodyPct() + 200 != 0
            || wmvStrapLowerBodyPct() + 150 != 0
            || wmvAirborneProfPct() + 50 != 0
            || wmvSaddlePct() != wmvStirrupsPct()
            || wmvAirBaseFallPct() != 0
            || wmvStrapFullBodyPct() >= wmvStrapLowerBodyPct()
        )
            ++bad;
        // the ten-foot granularity shared by the fall and the tumble
    if (wmvAbrasionPerFt() != 10
            || wmvFallFirstBandFt() != 10
        )
            ++bad;
        // the moderate stop window sits between its neighbors
    if (wmvStopModerateFt() - wmvStopCliffSevereFt() != 25
            || wmvStopGentleFt() - wmvStopModerateFt() != 25
        )
            ++bad;
        printf("R501 WSG movement fall fold audit: bad %d\n", bad);
        if (bad) return 1;
    }
    // ---- R502 WSG camp chain fold audit ----
