    if (dnpRideSpurFtPerRound() != 6
            || dnpRideSpurMaxTurns() != 4
            || dnpRideSpurLeadTurns() != 1
        )
            ++bad;
        // the healing pins: 1d3 emergency, 2 hp/day at rest, +2 poison save,
