    if (dnzWeeklyLoyaltyPenaltyPct() != 5
            || dnzDeceptionPenaltyPct() != 10
            || dnzExampleMonthPenaltyPct() != 20
        )
            ++bad;
        // the check outcomes: a separate roll per NPC, the failure meaning
