    if (dnzT20Key(0) != 0
            || dnzT20Lo(0) != 1
            || dnzT20Hi(0) != 20
            || dnzT20Key(1) != 1
            || dnzT20Lo(1) != 21
            || dnzT20Hi(1) != 55
        )
            ++bad;
        // the Table 20 tail bands: 56-85 sneaks away quietly as soon as
        // possible, 86-00 (pinned 86-100) freezes in place (the djvu garble
