    if (dnzT20Lo(2) != 56
            || dnzT20Hi(2) != 85
            || dnzT20Key(3) != 3
            || dnzT20Lo(3) != 86
            || dnzT20Hi(3) != 100
        )
            ++bad;
        // the recovery tail: the effect lasts until slain or returned to the
