    if (dnsRotOnsetYearsDice() != 1
            || dnsRotOnsetYearsSides() != 6
            || dnsCreosotePeriodMultiplier() != 2
        )
            ++bad;
        // the collapse ladder: 5% per multiple of the onset roll - the roll-1
