    if (dnsCollapseChancePerMultiplePct() != 5
            || dnsRollOneMaxYears() != 20
            || dnsRollSixMaxYears() != 120
        )
            ++bad;
        printf("R516 DSG structural decay audit: bad %d\n", bad);
        if (bad) return 1;
